"""The dog's collision cover (config/go2/dog_cover.json, generated by tools/go2_cover/build_dog_cover.py from the Go2's meshes): one box that contains the dog at its stand pose.
It contains the dog, it is current, the plate rests on the dog, and the arm at its named poses and over a pose sweep is checked against it. CPU only."""

import importlib.util
import json
import sys
from pathlib import Path

import numpy as np
import pytest

trimesh = pytest.importorskip("trimesh")

from piper_description import GO2_URDF, arm_base_pose, cover_report, dog_cover, go2_piper_curobo, go2_stand_pose, go2_world, mount_boxes, setup_config  # noqa: E402

pytestmark = pytest.mark.skipif(not GO2_URDF.exists(), reason="go2_studio's unitree_ros checkout is not here")
ROOT = Path(__file__).resolve().parents[3]
CFG = ROOT / "src/piper_description/config/go2"


def _generator():
    spec = importlib.util.spec_from_file_location("build_dog_cover", ROOT / "tools/go2_cover/build_dog_cover.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _R(q):
    w, x, y, z = q
    return np.array([[1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w)],
                     [2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w)],
                     [2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y)]])


def test_the_box_contains_every_point_of_the_dog_and_is_not_bigger_than_needed():
    """Random points on the dog's whole surface (not the vertices the generator used) are inside; no side has more than the margin of slack."""
    meshes = _generator().dog_meshes(GO2_URDF, go2_stand_pose())
    np.random.seed(1)
    pts = np.vstack([trimesh.sample.sample_surface(m, 4000)[0] for m in meshes.values()])
    b = dog_cover("base")["dog"]
    half, c = np.array(b["dims"]) / 2, np.array(b["pose"][:3])
    assert np.all(np.abs(pts - c) <= half + 1e-4)
    allv = np.vstack([m.vertices for m in meshes.values()])
    margin = cover_report()["policy"]["margin"]
    assert np.allclose(np.array(b["dims"]), (allv.max(0) - allv.min(0)) + 2 * margin, atol=1e-4)      # the exact bounding box (+ the policy margin), nothing hand-added


def test_the_committed_cover_is_current(tmp_path):
    """Regenerating from the Go2 description, the stand pose and the policy gives the committed files (generated, no hand edits)."""
    gen = _generator()
    old, sys.argv = sys.argv, ["build_dog_cover", "--out", str(tmp_path)]
    try:
        gen.main()
    finally:
        sys.argv = old
    assert json.loads((tmp_path / "dog_cover.json").read_text()) == json.loads((CFG / "dog_cover.json").read_text()), "stale: run tools/go2_cover/build_dog_cover.py"
    new, old_r = json.loads((tmp_path / "dog_cover_report.json").read_text()), cover_report()
    assert new["go2_description"] == old_r["go2_description"] and new["stand_pose"] == old_r["stand_pose"] and new["policy"] == old_r["policy"]
    assert old_r["stand_pose"] == setup_config()["stand_pose"] and old_r["all_points_inside"]


def test_the_plate_rests_on_the_dog():
    """The plate's bottom is at the top of the body shell under its footprint (config/go2/go2_setup.yaml says so): no gap, no sinking into the dog."""
    m = setup_config()["mount"]
    v = trimesh.load(GO2_URDF.parent.parent / "dae/base.dae", force="mesh").vertices      # `base` frame = the mesh frame (no joint origin)
    (cx, cy, cz), (sx, sy, sz) = m["plate_xyz"], m["plate_size"]
    top = v[(abs(v[:, 0] - cx) <= sx / 2) & (abs(v[:, 1] - cy) <= sy / 2), 2].max()
    assert cz - sz / 2 == pytest.approx(top, abs=0.002), f"plate bottom {cz - sz / 2:.4f}, body top under it {top:.4f}"


def test_the_world_is_the_dog_the_plate_and_the_payload_and_nothing_else():
    m = setup_config()["mount"]
    base, arm = go2_world("base"), go2_world("arm_base")
    assert set(base) == set(arm) == {"dog", "plate", *(b["name"] for b in m.get("payload_boxes") or [])}
    assert base["dog"] == dog_cover("base")["dog"] and base["plate"]["dims"] == m["plate_size"] and base["plate"]["pose"][:3] == m["plate_xyz"]
    for n in base:
        assert (arm_base_pose() @ [*arm[n]["pose"][:3], 1.0])[:3] == pytest.approx(base[n]["pose"][:3], abs=1e-6)
    assert arm["plate"]["pose"][:3] == pytest.approx([0, 0, -m["plate_size"][2] / 2], abs=1e-9)      # the arm's base_link frame is the plate's top face
    assert go2_world("arm_base", mount_rpy=(0, 0, np.pi))["dog"]["pose"][0] != pytest.approx(arm["dog"]["pose"][0])
    assert go2_piper_curobo()["world"]["cuboid"] == arm


def test_payload_boxes_become_world_boxes(monkeypatch):
    import piper_description.go2 as g
    cfg = g.setup_config()
    cfg["mount"]["payload_boxes"] = [{"name": "zed_box", "size": [0.1, 0.08, 0.04], "xyz": [-0.2, 0.0, 0.1], "rpy": [0, 0, 0.5]}]
    monkeypatch.setattr(g, "setup_config", lambda: cfg)
    w = g.go2_world("base")
    assert set(w) == {"dog", "plate", "zed_box"} and w["zed_box"]["dims"] == [0.1, 0.08, 0.04] and w["zed_box"]["pose"][:3] == [-0.2, 0.0, 0.1]
    assert w["zed_box"]["pose"][3:] != [1.0, 0.0, 0.0, 0.0]                                  # the yaw is applied
    assert set(g.mount_boxes()) == {"plate", "zed_box"}


def _clearance(c, r, box):
    local = _R(box["pose"][3:]).T @ (np.asarray(c) - np.array(box["pose"][:3]))
    half = np.array(box["dims"]) / 2
    if np.all(np.abs(local) < half):
        return -float(np.min(half - np.abs(local))) - r
    return float(np.linalg.norm(np.maximum(np.abs(local) - half, 0.0))) - r


def _min_clearances(q_list):
    """Per pose: {link: smallest distance from any collision sphere of the link to the dog's box (negative = inside)}."""
    from piper_core.kinematics import Kinematics
    cfg = go2_piper_curobo()
    spheres = cfg["robot"]["kinematics"]["collision_spheres"]
    kin = Kinematics.from_assets(camera="zedxm")
    boxes = list(cfg["world"]["cuboid"].values())
    centers = {l: np.array([s["center"] for s in lst]) for l, lst in spheres.items() if lst}
    radii = {l: np.array([s["radius"] for s in lst]) for l, lst in spheres.items() if lst}
    out = []
    for q in q_list:
        worst = {}
        for l, C in centers.items():
            P = (kin.pose(q, l) @ np.hstack([C, np.ones((len(C), 1))]).T).T[:, :3]
            worst[l] = min(_clearance(p, r, b) for p, r in zip(P, radii[l]) for b in boxes)
        out.append(worst)
    return out


def test_arm_is_clear_of_the_dog_at_the_named_poses():
    pytest.importorskip("piper_assets")
    from piper_core.arm_cli import READY
    out = _min_clearances([[0.0, 0.01, -0.01, 0.0, 0.0, 0.0], list(READY)])
    for name, worst in zip(("zero", "ready"), out):
        link = min(worst, key=worst.get)
        print(f"{name}: closest {link} {worst[link] * 1000:.2f} mm to the dog's box or the plate")
        assert worst[link] > 0.0, f"{link} is inside the dog's box or the plate at {name} ({worst[link] * 1000:.2f} mm)"


@pytest.mark.xfail(strict=True, reason="mount ESTIMATE (plate 30 mm): the arm's base is 1.96 mm above the dog's box, inside the model's 2.0 mm sphere buffer; a plate of 31 mm or more (or the measured mount) clears it")
def test_the_arm_base_clears_the_dog_by_more_than_the_models_sphere_buffer():
    """The box's top is the dog's highest point (the shoulder hump, z = 0.0893 in the Go2 base frame); the arm's base spheres start 3 mm above the plate top. A planner that applies the model's
    sphere buffer sees base_link in contact with the dog at every pose unless the plate top is at least `buffer` above the box top."""
    pytest.importorskip("piper_assets")
    import piper_assets as pa
    buffer = pa.curobo_config()["kinematics"]["collision_sphere_buffer"]
    assert _min_clearances([[0.0, 0.01, -0.01, 0.0, 0.0, 0.0]])[0]["base_link"] > buffer


def test_sweep_of_random_poses_reports_how_often_the_arm_would_hit_the_dog():
    """Information, not a rule: poses inside the planning limits that put arm spheres into the dog's box or the plate (a planner avoids them). A sweep that never hits, or always hits, is suspect."""
    pytest.importorskip("piper_assets")
    import piper_assets as pa
    lim = pa.limits().as_arrays("planning")
    lo, hi = np.array(lim[0]), np.array(lim[1])
    rng = np.random.default_rng(0)
    qs = [lo + rng.random(6) * (hi - lo) for _ in range(150)]
    hits = sum(1 for w in _min_clearances(qs) if min(w.values()) <= 0.0)
    print(f"{hits} of {len(qs)} random poses inside the limits put the arm into the dog's box or the plate")
    assert 0 < hits < len(qs)
